from rest_framework import generics, permissions
from .models import WholesalePriceTierMatrix
from .serializers import WholesalePriceTierMatrixSerializer

class IsAuthorizedSupplier(permissions.BasePermission):
    def has_object_permission(self, request, view, obj):
        # Both read and write operations require ownership by the supplier
        return obj.supplier == getattr(request.user, "supplier_account", None)

class WholesalePriceMatrixDetailView(generics.RetrieveUpdateAPIView):
    serializer_class = WholesalePriceTierMatrixSerializer
    permission_classes = [permissions.IsAuthenticated, IsAuthorizedSupplier]
    lookup_field = "matrix_code"

    def get_queryset(self):
        supplier = getattr(self.request.user, "supplier_account", None)
        if not supplier:
            return WholesalePriceTierMatrix.objects.none()
        return WholesalePriceTierMatrix.objects.filter(supplier=supplier)
